const CATEGORIES=["Culture","Music","Food","Adventure","Religious","Sports"];function normalize(t){return"string"==typeof t?t.trim().toLowerCase():""}function monthInRange(t,e,n){return"number"==typeof t&&"number"==typeof e&&"number"==typeof n&&(e<=n?t>=e&&t<=n:t>=e||t<=n)}function rangesOverlap(t,e,n,r){for(let o=1;o<=12;o++)if(monthInRange(o,t,e)&&monthInRange(o,n,r))return!0;return!1}export class EventRecommendationEngine{constructor(t={}){this.events=t.events||[],this.bookmarks=new Set(t.bookmarks||[])}static get CATEGORIES(){return CATEGORIES.slice()}filterByDestination(t,{destinationId:e,state:n}={}){return e||n?t.filter(t=>!(!e||t.destinationId!==e)||!(!n||normalize(t.state)!==normalize(n))):t}filterByDateRange(t,e,n){if(!e)return t;const r=e instanceof Date?e:new Date(e),o=n?n instanceof Date?n:new Date(n):r;if(isNaN(r.getTime()))return t;const a=isNaN(o.getTime())?r:o,s=r.getMonth()+1,i=a.getMonth()+1;return t.filter(t=>rangesOverlap(t.startMonth,t.endMonth,s,i))}filterByCategories(t,e){if(!e||0===e.length)return t;const n=e.map(normalize);return t.filter(t=>{const e=normalize(t.category),r=(t.tags||[]).map(normalize);return n.includes(e)||r.some(t=>n.includes(t))})}scoreEvent(t,e=[]){const n=Math.max(0,Math.min(10,t.popularity||0))/10;if(!e||0===e.length)return{score:n,matchedInterests:[]};const r=e.map(normalize),o=[normalize(t.category),...(t.tags||[]).map(normalize)],a=r.filter(t=>o.includes(t));return{score:.5*n+.5*(a.length/r.length),matchedInterests:a}}recommend(t={}){const{destinationId:e,state:n,startDate:r,endDate:o,interests:a=[],categories:s=[],limit:i=10}=t;let m=this.events;m=this.filterByDestination(m,{destinationId:e,state:n}),m=this.filterByDateRange(m,r,o),m=this.filterByCategories(m,s);return m.map(t=>{const{score:e,matchedInterests:n}=this.scoreEvent(t,a);return{event:t,matchScore:e,matchedInterests:n,isBookmarked:this.bookmarks.has(t.id)}}).sort((t,e)=>e.matchScore-t.matchScore).slice(0,i)}toggleBookmark(t){return!!t&&(this.bookmarks.has(t)?(this.bookmarks.delete(t),!1):(this.bookmarks.add(t),!0))}isBookmarked(t){return this.bookmarks.has(t)}getBookmarkIds(){return Array.from(this.bookmarks)}getBookmarkedEvents(){return this.events.filter(t=>this.bookmarks.has(t.id))}static buildItineraryEntry(t,{date:e}={}){return t?{id:`event_${t.id}_${Date.now()}`,type:"event",eventId:t.id,title:t.name,activity:`Attend ${t.name}`,location:t.location||t.state,category:t.category,date:e||null}:null}static addEventToItinerary(t,e,n){const r=EventRecommendationEngine.buildItineraryEntry(e,n);return r?[...t||[],r]:t||[]}static removeEventFromItinerary(t,e){return(t||[]).filter(t=>t.id!==e)}static getUpcomingReminders(t,e=new Date,n=1){const r=e.getMonth()+1,o=[];for(const e of t||[])for(let t=0;t<=n;t++){if(monthInRange((r-1+t)%12+1,e.startMonth,e.endMonth)){o.push({event:e,monthsUntil:t});break}}return o.sort((t,e)=>t.monthsUntil-e.monthsUntil)}}export const EVENT_ENGINE_INTERNALS={monthInRange:monthInRange,rangesOverlap:rangesOverlap,normalize:normalize};